INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/1', '샘플 데이터', '[샘플] 사회초년생을 위한 첫 적금 고르는 법', '사회초년생이 처음 저축을 시작할 때는 매달 일정 금액을 넣는 적금이 부담이 적다. 적금은 만기까지 꾸준히 넣어야 약속한 금리를 받을 수 있다. 금리가 높은 상품이라도 중도에 해지하면 이자가 크게 줄어든다. 그래서 첫 적금은 무리하지 않는 금액으로 시작하는 것이 좋다. 청년을 위한 정책 상품은 일반 상품보다 혜택이 클 수 있으니 조건을 함께 확인한다.', '청년', now() - interval '1 hours') ON CONFLICT (source_url) DO NOTHING;
