INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT id, 1, '적금을 중도에 해지하면 어떻게 되나요?', '["이자가 크게 줄어든다", "이자가 두 배가 된다", "원금이 늘어난다", "아무 변화가 없다"]'::jsonb, 0, '기사에서 중도 해지하면 이자가 크게 줄어든다고 설명한다.', '[1]'::jsonb, 'sample', 'sample' FROM news_articles WHERE source_url = 'local-sample://article/1' ON CONFLICT DO NOTHING;
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT id, 2, '첫 적금을 시작할 때 권하는 방법은?', '["한 달만 넣고 해지", "무리하지 않는 금액으로 시작", "가능한 최대 금액으로 시작", "대출을 받아 시작"]'::jsonb, 1, '무리하지 않는 금액으로 시작하는 것이 좋다고 했다.', '[1]'::jsonb, 'sample', 'sample' FROM news_articles WHERE source_url = 'local-sample://article/1' ON CONFLICT DO NOTHING;
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT id, 3, '청년 정책 상품에 대해 기사가 말한 것은?', '["일반 상품보다 항상 불리하다", "가입이 금지되어 있다", "혜택이 클 수 있으니 조건을 확인한다", "누구나 조건 없이 가입한다"]'::jsonb, 2, '혜택이 클 수 있으니 조건을 함께 확인하라고 했다.', '[1]'::jsonb, 'sample', 'sample' FROM news_articles WHERE source_url = 'local-sample://article/1' ON CONFLICT DO NOTHING;
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/2', '샘플 데이터', '[샘플] ETF와 배당, 처음 투자할 때 알아둘 점', 'ETF는 여러 주식을 한 바구니에 담아 거래소에서 사고팔 수 있게 만든 상품이다. 한 종목에 모든 돈을 넣는 것보다 위험을 나눌 수 있다는 장점이 있다. 일부 ETF와 주식은 회사가 번 이익의 일부를 배당으로 나눠 준다. 배당은 정해진 시기에 지급되며 회사 사정에 따라 줄어들 수도 있다. 투자 상품은 원금이 보장되지 않으므로 여유 자금으로 시작한다.', '투자', now() - interval '2 hours') ON CONFLICT (source_url) DO NOTHING;
