INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT id, 9, 0, 5 FROM news_articles WHERE source_url = 'local-sample://article/3';
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT id, 1, '인플레이션이란 무엇인가요?', '["가격이 전반적으로 내리는 현상", "금리가 0이 되는 현상", "주가가 오르는 현상", "물건과 서비스 가격이 전반적으로 오르는 현상"]'::jsonb, 3, '가격이 전반적으로 오르는 현상이라고 정의했다.', '[1]'::jsonb, 'sample', 'sample' FROM news_articles WHERE source_url = 'local-sample://article/3' ON CONFLICT DO NOTHING;
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT id, 2, '물가가 빠르게 오를 때 중앙은행이 하는 일은?', '["금리를 올린다", "금리를 내린다", "돈을 더 찍는다", "세금을 없앤다"]'::jsonb, 0, '소비와 대출을 줄이려고 금리를 올린다고 했다.', '[1]'::jsonb, 'sample', 'sample' FROM news_articles WHERE source_url = 'local-sample://article/3' ON CONFLICT DO NOTHING;
INSERT INTO quizzes(article_id, quiz_order, question, choices, answer_index, explanation, source_sentence_ids, model_version, prompt_version) SELECT id, 3, '금리가 오르면 함께 커지는 것은?', '["주식 배당", "대출 이자 부담", "물건 가격 할인", "예금 원금"]'::jsonb, 1, '대출 이자 부담도 함께 커진다고 했다.', '[1]'::jsonb, 'sample', 'sample' FROM news_articles WHERE source_url = 'local-sample://article/3' ON CONFLICT DO NOTHING;
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/4', '샘플 데이터', '[샘플] 전세대출 받기 전에 확인할 세 가지', '전세대출은 전세 보증금을 마련하기 위해 받는 대출이다. 먼저 집주인이 실제 소유자인지 등기부등본으로 확인해야 한다. 다음으로 보증금을 돌려받지 못할 위험에 대비해 보증보험 가입이 가능한지 살핀다. 마지막으로 대출 금리와 상환 방식을 비교해 매달 낼 이자를 계산한다. 계약 전에 꼼꼼히 확인할수록 분쟁을 줄일 수 있다.', '부동산', now() - interval '4 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT id, 7, 0, 4 FROM news_articles WHERE source_url = 'local-sample://article/4';
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT id, 8, 119, 121 FROM news_articles WHERE source_url = 'local-sample://article/4';
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/5', '샘플 데이터', '[샘플] 신용대출, 한도보다 중요한 것', '신용대출은 담보 없이 개인의 신용을 바탕으로 받는 대출이다. 한도가 크게 나오더라도 필요한 만큼만 빌리는 것이 좋다. 금리가 변동형이면 시장 금리에 따라 매달 이자가 달라질 수 있다. 연체가 생기면 신용점수가 떨어져 다음 대출이 어려워진다. 상환 계획을 먼저 세우고 대출을 받는 습관이 중요하다.', '금융', now() - interval '5 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT id, 6, 0, 4 FROM news_articles WHERE source_url = 'local-sample://article/5';
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT id, 8, 66, 68 FROM news_articles WHERE source_url = 'local-sample://article/5';
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/6', '샘플 데이터', '[샘플] 목돈 만들기, 적금과 예금의 차이', '적금은 매달 돈을 나눠 넣고, 예금은 한 번에 맡기는 방식이다. 모아 둔 돈이 없다면 적금으로 목돈을 만드는 것이 현실적이다. 이미 목돈이 있다면 예금에 맡겨 이자를 받을 수 있다. 두 상품 모두 금리와 만기를 비교해 고르는 것이 기본이다. 비상금은 언제든 꺼낼 수 있는 통장에 따로 두는 것이 안전하다.', '저축', now() - interval '6 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT id, 8, 110, 112 FROM news_articles WHERE source_url = 'local-sample://article/6';
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT id, 10, 0, 2 FROM news_articles WHERE source_url = 'local-sample://article/6';
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/7', '샘플 데이터', '[샘플] 청년 지원 정책, 신청 전에 볼 것', '청년 지원 정책은 나이와 소득, 거주 지역에 따라 신청 조건이 다르다. 같은 이름의 사업이라도 지역마다 지원 내용이 다를 수 있다. 신청 기간을 놓치면 다음 해까지 기다려야 하는 경우가 많다. 필요한 서류를 미리 준비하면 신청 과정이 훨씬 수월하다. 정확한 내용은 담당 기관의 공고에서 확인한다.', '정책', now() - interval '7 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO news_articles(source_url, source_name, title, content, category, published_at) VALUES ('local-sample://article/8', '샘플 데이터', '[샘플] 첫 월급 받기 전에 알아둘 돈 관리', '취업 후 첫 월급을 받으면 세금과 보험료가 빠진 금액이 들어온다. 먼저 고정 지출을 정리하고 남는 돈의 일부를 저축으로 돌린다. 적금이나 자동이체를 활용하면 저축을 꾸준히 이어가기 쉽다. 카드 사용액은 다음 달 월급에서 빠져나가므로 한도를 정해 두는 것이 좋다. 작은 금액이라도 비상금을 따로 모으는 습관이 도움이 된다.', '취업', now() - interval '8 hours') ON CONFLICT (source_url) DO NOTHING;
INSERT INTO article_term_highlights(article_id, term_id, position_start, position_end) SELECT id, 10, 72, 74 FROM news_articles WHERE source_url = 'local-sample://article/8';
